display.text:
/*
 * Веб-интерфейс оболочки.
 *
 * Всё, что может сделать браузер, делает браузер. Нативный мост используется
 * ровно для трёх вещей, которые из страницы невозможны: выбор папки на
 * устройстве, чтение/запись настроек приложения и запросы к моделям (у них
 * нет CORS-заголовков, поэтому из JS их не сделать).
 *
 * Данные с устройства идут не мостом, а с локального сервера оболочки: там
 * потоковый отдача страниц архива, без base64 и без кэша.
 */
'use strict';

const qs = new URLSearchParams(location.search);
const TOKEN = qs.get('k') || '';
const TAB = qs.get('tab') || 'library';
const BASE = location.origin;

const view = document.getElementById('view');
const titleEl = document.getElementById('title');
const statusEl = document.getElementById('status');

const TITLES = {
  library: 'Библиотека',
  reader: 'Читалка',
  chat: 'AI-чат',
  settings: 'Настройки',
};

const state = {
  uri: null,        // текущая папка
  archive: null,    // текущий архив
  pages: [],
  page: 0,
};

function setStatus(text) { statusEl.textContent = text || ''; }
function setTitle(text) { titleEl.textContent = text; }

/** JSON с локального сервера оболочки. */
async function api(path, params) {
  const url = new URL(BASE + path);
  url.searchParams.set('k', TOKEN);
  Object.entries(params || {}).forEach(([k, v]) => {
    if (v !== undefined && v !== null) url.searchParams.set(k, v);
  });
  const res = await fetch(url.toString());
  const text = await res.text();
  if (!res.ok) throw new Error(text || ('HTTP ' + res.status));
  return text ? JSON.parse(text) : null;
}

function el(tag, props, children) {
  const node = document.createElement(tag);
  Object.entries(props || {}).forEach(([k, v]) => {
    if (k === 'class') node.className = v;
    else if (k === 'text') node.textContent = v;
    else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
    else if (v !== undefined) node.setAttribute(k, v);
  });
  (Array.isArray(children) ? children : [children]).forEach((c) => {
    if (c === null || c === undefined) return;
    node.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
  });
  return node;
}

function showError(message) {
  view.replaceChildren(el('div', { class: 'error', text: String(message || 'Что-то пошло не так') }));
}

function humanSize(bytes) {
  if (!bytes) return '';
  const units = ['Б', 'КБ', 'МБ', 'ГБ'];
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < units.length - 1) { value /= 1024; i++; }
  return (i === 0 ? value : value.toFixed(1)) + ' ' + units[i];
}

/* --- библиотека ---------------------------------------------------------- */

const IMAGES = ['jpg', 'jpeg', 'png', 'webp', 'gif', 'avif', 'jxl'];
const ARCHIVES = ['zip', 'cbz'];

async function renderLibrary() {
  setTitle(TITLES.library);
  view.replaceChildren(el('div', { class: 'hint', text: 'Читаем с устройства' }));

  const roots = await api('/api/roots');
  if (!roots.length) {
    view.replaceChildren(
      el('div', { class: 'hint', text: 'Корень не выбран. Папка с CBZ/картинками лежит на устройстве — укажите её, права сохранятся.' }),
      el('button', { class: 'primary', text: 'Выбрать папку', onclick: () => Yomi.pickLibraryFolder() }),
    );
    setStatus('');
    return;
  }

  const chips = el('div', { class: 'row' }, roots.map((r) => el('button', {
    text: r.name || 'Корень',
    onclick: () => { state.uri = r.uri; renderList(); },
  })));
  const actions = el('div', { class: 'row', style: 'margin:10px 0' }, [
    el('button', { text: 'Обновить', onclick: () => renderList() }),
    el('button', { text: 'Другая папка', onclick: () => Yomi.pickLibraryFolder() }),
  ]);
  view.replaceChildren(chips, actions);
  if (!state.uri) state.uri = roots[0].uri;
  await renderList();
}

async function renderList() {
  let nodes = [];
  try {
    nodes = await api('/api/list', { uri: state.uri });
  } catch (e) {
    showError(e.message);
    return;
  }
  const items = nodes
    .slice()
    .sort((a, b) => (b.dir - a.dir) || a.name.localeCompare(b.name, 'ru'));

  if (!items.length) {
    view.appendChild(el('div', { class: 'hint', text: 'Папка пуста. Сюда кладут папки с картинками или CBZ/CBR.' }));
    setStatus('');
    return;
  }
  const list = el('ul', {}, items.map((node) => el('li', {
    class: 'item' + (node.dir ? ' dir' : ''),
    onclick: () => (node.dir ? enterDir(node) : openItem(node)),
  }, [
    el('span', { class: 'name', text: node.name }),
    el('span', { class: 'meta', text: node.dir ? 'папка' : humanSize(node.size) }),
  ])));
  view.appendChild(list);
  setStatus(items.length + ' шт.');
}

function enterDir(node) {
  state.uri = node.uri;
  renderList();
}

async function openItem(node) {
  if (ARCHIVES.includes(node.ext)) {
    state.archive = node;
    await renderReader();
    return;
  }
  if (IMAGES.includes(node.ext)) {
    // Одиночная картинка: показываем как одностраничную «главу».
    state.archive = null;
    state.pages = [{ name: node.name, url: fileUrl(node.uri) }];
    state.page = 0;
    await renderReader();
    return;
  }
  if (['pdf', 'epub', 'fb2', 'txt', 'md', 'docx'].includes(node.ext)) {
    state.archive = null;
    state.pages = [{ name: node.name, url: fileUrl(node.uri), book: true }];
    state.page = 0;
    await renderReader();
  }
}

const fileUrl = (uri) => `${BASE}/api/file?k=${encodeURIComponent(TOKEN)}&uri=${encodeURIComponent(uri)}`;
const entryUrl = (uri, name) =>
  `${BASE}/api/zip/entry?k=${encodeURIComponent(TOKEN)}&uri=${encodeURIComponent(uri)}&e=${encodeURIComponent(name)}`;

/* --- читалка ------------------------------------------------------------- */

async function renderReader() {
  setTitle(TITLES.reader);
  if (!state.archive && !state.pages.length) {
    view.replaceChildren(el('div', { class: 'hint', text: 'Откройте архив или картинку в библиотеке.' }));
    return;
  }
  if (state.archive && !state.pages.length) {
    setStatus('Читаю каталог архива…');
    try {
      const entries = await api('/api/zip/list', { uri: state.archive.uri });
      state.pages = entries.map((e) => ({ name: e.name, url: entryUrl(state.archive.uri, e.name) }));
    } catch (e) {
      showError('Каталог архива не прочитан: ' + e.message);
      return;
    }
  }
  if (!state.pages.length) {
    showError('В архиве нет картинок');
    return;
  }
  state.page = Math.min(state.page, state.pages.length - 1);
  setStatus(state.archive ? state.archive.name : '');
  view.replaceChildren(el('div', { id: 'pages' }, state.pages.map((p, i) => el('button', {
    class: i === state.page ? 'active' : '',
    text: String(i + 1),
    onclick: () => { state.page = i; showPage(); },
  }))));

  const pageBox = el('div', { id: 'page' });
  const ocrBox = el('div', { id: 'ocr', text: '' });
  const actions = el('div', { class: 'row', style: 'margin:10px 0' }, [
    el('button', { text: '‹', onclick: () => step(-1) }),
    el('button', { text: '›', onclick: () => step(1) }),
    el('button', {
      class: 'primary',
      text: 'Распознать',
      onclick: () => recognizeCurrentPage(ocrBox),
    }),
  ]);
  view.append(actions, pageBox, ocrBox);
  showPage();
}

function step(delta) {
  const next = state.page + delta;
  if (next < 0 || next >= state.pages.length) return;
  state.page = next;
  showPage();
}

function showPage() {
  const current = state.pages[state.page];
  const box = document.getElementById('page');
  const ocr = document.getElementById('ocr');
  if (!box || !current) return;
  box.replaceChildren(el('img', { src: current.url, alt: current.name }));
  document.querySelectorAll('#pages button').forEach((b, i) => b.classList.toggle('active', i === state.page));
  if (ocr) ocr.textContent = '';
  setStatus((state.page + 1) + ' / ' + state.pages.length);
}

/**
 * Распознать страницу. Картинка уезжает в модель как base64 — единственное
 * место, где это допустимо: одна страница по кнопке, а не поток картинок.
 */
async function recognizeCurrentPage(ocrBox) {
  const current = state.pages[state.page];
  if (!current) return;
  ocrBox.textContent = 'Распознаю…';
  try {
    const blob = await (await fetch(current.url)).blob();
    const base64 = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
    const answer = JSON.parse(Yomi.recognizeImage(base64, 'Распознай весь текст на этой странице comics. Ответь только текстом.'));
    if (answer.error) ocrBox.textContent = 'Ошибка: ' + answer.error;
    else ocrBox.textContent = answer.text || 'Текст не найден.';
  } catch (e) {
    ocrBox.textContent = 'Ошибка распознавания: ' + e.message;
  }
}

/* --- чат ----------------------------------------------------------------- */

const chatlog = [];

async function renderChat() {
  setTitle(TITLES.chat);
  if (!Yomi.hasApiKey('openrouter')) {
    view.replaceChildren(
      el('div', { class: 'hint', text: 'Ключ OpenRouter хранится в настройках приложения и в веб не отдаётся.' }),
      el('button', { class: 'primary', text: 'Вписать ключ', onclick: () => { location.search = '?k=' + TOKEN + '&tab=settings'; } }),
    );
    return;
  }
  view.replaceChildren(
    el('div', { id: 'chatlog' }),
    el('textarea', { id: 'prompt', placeholder: 'Спроси что-нибудь' }),
    el('div', { class: 'row', style: 'margin-top:8px' }, [
      el('button', {
        class: 'primary',
        text: 'Спросить',
        onclick: () => send(),
      }),
    ]),
  );
  redrawChat();
}

function redrawChat() {
  const log = document.getElementById('chatlog');
  if (!log) return;
  log.replaceChildren(...chatlog.map((m) => el('div', { class: 'msg ' + m.role, text: m.text })));
  log.lastElementChild?.scrollIntoView({ block: 'end' });
}

async function send() {
  const input = document.getElementById('prompt');
  const text = input.value.trim();
  if (!text) return;
  input.value = '';
  chatlog.push({ role: 'user', text });
  redrawChat();
  chatlog.push({ role: 'ai', text: 'Думаю…' });
  redrawChat();
  const payload = chatlog
    .filter((m) => m.role === 'user' || (m.role === 'ai' && m.text !== 'Думаю…'))
    .map((m) => ({ role: m.role === 'user' ? 'user' : 'assistant', content: m.text }));
  const answer = JSON.parse(Yomi.chat(JSON.stringify(payload), ''));
  chatlog.pop();
  chatlog.push({ role: answer.error ? 'error' : 'ai', text: answer.error || answer.text });
  redrawChat();
}

/* --- настройки ----------------------------------------------------------- */

async function renderSettings() {
  setTitle(TITLES.settings);
  const prefs = JSON.parse(Yomi.getPrefs('ui.') || '{}');
  const key = Yomi.hasApiKey('openrouter');
  view.replaceChildren(
    el('label', { class: 'field' }, [
      el('span', { text: 'Ключ OpenRouter (распознавание и чат)' }),
      el('input', { type: 'password', id: 'key', value: '', placeholder: key ? 'сохранён' : 'не задан' }),
    ]),
    el('div', { class: 'row' }, [
      el('button', {
        class: 'primary',
        text: 'Сохранить ключ',
        onclick: () => {
          const value = document.getElementById('key').value.trim();
          if (value) Yomi.setApiKey('openrouter', value);
          setStatus(value ? 'Ключ сохранён' : 'Пусто — ключ не менялся');
          renderSettings();
        },
      }),
    ]),
    el('label', { class: 'field' }, [
      el('span', { text: 'Модель распознавания' }),
      el('input', {
        type: 'text',
        value: prefs['ui.ocr.model'] || 'google/gemini-2.5-flash',
        onchange: (e) => Yomi.setPref('ui.ocr.model', e.target.value),
      }),
    ]),
    el('label', { class: 'field' }, [
      el('span', { text: 'Показывать номера страниц' }),
      el('input', {
        type: 'checkbox',
        checked: prefs['ui.ocr.showPages'] !== '0',
        onchange: (e) => Yomi.setPref('ui.ocr.showPages', e.target.checked ? '1' : '0'),
      }),
    ]),
    el('div', { class: 'hint', text: 'Версия оболочки: ' + Yomi.appVersion() }),
  );
}

/* --- маршрутизация ------------------------------------------------------- */

const ROUTES = {
  library: renderLibrary,
  reader: renderReader,
  chat: renderChat,
  settings: renderSettings,
};

window.YomiShell = {
  event(name) {
    if (name === 'library:roots-changed') renderLibrary();
  },
};

(ROUTES[TAB] || renderLibrary)().catch((e) => showError(e.message));

