plugins {
    // AGP 9 умеет Kotlin сам, отдельный плагин в нём запрещён.
    alias(libs.plugins.android.application)
}

/**
 * Оболочка Yomikai: нативная вкладка браузера и веб-интерфейс вместо
 * библиотеки, читалки и настроек.
 *
 * Здесь НЕТ ни Compose, ни локального OCR, ни своей базы, ни нативных
 * библиотек. Локальное распознавание в оболочке невозможно: оно требует
 * LiteRT (5,65 МБ) и ML Kit (11,76 МБ), а это ровно тот вес, ради которого
 * оболочка делалась. Распознавание идёт через сеть мостом, интерфейс
 * грузится из assets по защищённому origin.
 */
android {
    namespace = "app.yomikai.shell"
    compileSdk = 37

    defaultConfig {
        applicationId = "app.yomikai.shell"
        minSdk = 26
        targetSdk = 36
        versionCode = 1
        versionName = "0.1.0"
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
        }
        debug {
            applicationIdSuffix = ".debug"
            isMinifyEnabled = false
        }
    }

    signingConfigs {
        // Ключ и пароли приходят из CI переменными окружения, а не
        // gradle-свойствами: providers.gradleProperty() их не видит, и
        // сборка выходила неподписанной. Без переменных release собирается
        // как unsigned — это нужно гейту, который меряет размер.
        val store = System.getenv("SHELL_KEYSTORE")
        if (!store.isNullOrBlank()) {
            create("release") {
                // Путь задаётся от корня репозитория: file() внутри модуля app
                // разрешил бы app/app/shell.p12.
                storeFile = rootProject.file(store)
                storePassword = System.getenv("SHELL_STORE_PASSWORD")
                keyAlias = System.getenv("SHELL_KEY_ALIAS")
                keyPassword = System.getenv("SHELL_KEY_PASSWORD")
            }
        }
    }

    buildTypes.getByName("release") {
        signingConfigs.findByName("release")?.let { signingConfig = it }
    }

    // Никаких ABI-сплитов и нативных библиотек: единственная нативная
    // вкладка — системный WebView, он в платформе.
    packaging {
        resources {
            excludes += setOf(
                "META-INF/*.version",
                "META-INF/*.kotlin_module",
                "DebugProbesKt.bin",
                "kotlin-tooling-metadata.json",
            )
        }
    }

    buildFeatures {
        buildConfig = true
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
        isCoreLibraryDesugaringEnabled = false
    }

}

dependencies {
    implementation(libs.androidx.core.ktx)
    implementation(libs.androidx.activity)
    implementation(libs.androidx.appcompat)
    // WebViewAssetLoader: раздача веб-интерфейса с https-origin вместо
    // file://. Без него страница не имеет нормального origin, и браузер
    // отказывает в доступе к локальным ресурсам и кешам.
    implementation(libs.androidx.webkit)

    testImplementation(libs.junit.jupiter)
}
